  const edit=(r:any)=>setX({id:r.id,campaignId:r.campaign_id,slotKey:r.slot_key,sourceType:r.source_type,productId:r.product_id||"",collectionId:r.collection_id||"",query:r.query_json||"{}",title:r.title||"",eyebrow:r.eyebrow||"",body:r.body||"",ctaLabel:r.cta_label||"",ctaHref:r.cta_href||"",imageUrl:r.image_url||"",badge:r.badge||"",sortOrder:r.sort_order,weight:r.weight,sponsored:!!r.sponsored,sponsorName:r.sponsor_name||"",territoryCode:r.territory_code||"",languageCode:r.language_code||"",experimentId:r.experiment_id||"",experimentVariant:r.experiment_variant||"",startsAt:r.starts_at||"",endsAt:r.ends_at||"",active:!!r.active});
  const save=async()=>{try{await adminApi("/admin/merchandising/placement",token,"POST",{...x,query:jsonObject(x.query),productId:x.productId||null,collectionId:x.collectionId||null,sortOrder:Number(x.sortOrder),weight:Number(x.weight),territoryCode:x.territoryCode||null,languageCode:x.languageCode||null,experimentId:x.experimentId||null,experimentVariant:x.experimentVariant||null,startsAt:x.startsAt||null,endsAt:x.endsAt||null});toast.success("Placement saved");await reload();}catch(e){toast.error((e as Error).message)}};
