  const save=async()=>{try{await adminApi("/admin/merchandising/experiment",token,"POST",{...x,variants:jsonArray(x.variants),startsAt:x.startsAt||null,endsAt:x.endsAt||null});toast.success("Experiment saved");await reload();}catch(e){toast.error((e as Error).message)}};
  return <AdminSplit title="Experiments" help="Visitor bucketing is deterministic, so the same person stays in the same weighted variant. Placements can target one experiment variant without changing storefront code."><FormCard title={x.id?"Edit experiment":"New experiment"}><Two><Field label="Name"><input value={x.name} onChange={e=>setX({...x,name:val(e)})}/></Field><Field label="Key"><input value={x.experimentKey} onChange={e=>setX({...x,experimentKey:val(e).toLowerCase().replace(/[^a-z0-9-]/g,"-")})}/></Field></Two><Field label="Status"><select value={x.status} onChange={e=>setX({...x,status:val(e)})}><option>draft</option><option>published</option><option>paused</option><option>completed</option></select></Field><Two><Field label="Starts at"><input type="datetime-local" value={(x.startsAt||"").replace(/Z$/," ").trim().slice(0,16)} onChange={e=>setX({...x,startsAt:e.target.value?new Date(e.target.value).toISOString():""})}/></Field><Field label="Ends at"><input type="datetime-local" value={(x.endsAt||"").replace(/Z$/," ").trim().slice(0,16)} onChange={e=>setX({...x,endsAt:e.target.value?new Date(e.target.value).toISOString():""})}/></Field></Two><Field label="Weighted variants (JSON)"><textarea value={x.variants} onChange={e=>setX({...x,variants:val(e)})}/></Field><SaveButton onClick={save}/></FormCard><Rows rows={rows} title={(r)=>r.name} subtitle={(r)=>`${r.status} · ${r.experiment_key}`} onEdit={edit}/></AdminSplit>;
