function Taxonomy({token,data,reload}:{token:string;data:any;reload:()=>Promise<void>}) {
  const [node,setNode]=useState<any>({name:"",slug:"",parentId:"",description:"",sortOrder:0,visible:true,featured:false,seoTitle:"",seoDescription:""});
  const [mapping,setMapping]=useState<any>({taxonomyNodeId:"",sourceScheme:"*",sourceValue:"",matchMode:"contains",priority:0,active:true});
  const [manual,setManual]=useState<any>({editionId:"",taxonomyNodeIds:[] as string[]});
  const edit=(r:any)=>setNode({id:r.id,name:r.name,slug:r.slug,parentId:r.parent_id||"",description:r.description||"",sortOrder:r.sort_order,visible:!!r.visible,featured:!!r.featured,seoTitle:r.seo_title||"",seoDescription:r.seo_description||""});
  const saveNode=async()=>{try{await adminApi("/admin/taxonomy/node",token,"POST",{...node,parentId:node.parentId||null,sortOrder:Number(node.sortOrder)});toast.success("Category saved");await reload();}catch(e){toast.error((e as Error).message)}};
  const saveMap=async()=>{try{await adminApi("/admin/taxonomy/mapping",token,"POST",{...mapping,priority:Number(mapping.priority)});toast.success("Mapping saved · reclassifying catalog");let after="";for(let i=0;i<1000;i++){const r:any=await adminApi("/admin/taxonomy/sync",token,"POST",{limit:500,afterEditionId:after});if(!r.nextAfter)break;after=r.nextAfter;}toast.success("Retail taxonomy is up to date");await reload();}catch(e){toast.error((e as Error).message)}};
  const saveManual=async()=>{try{await adminApi("/admin/taxonomy/manual",token,"POST",manual);toast.success("Editorial taxonomy override saved");await reload();}catch(e){toast.error((e as Error).message)}};
  const sync=async()=>{try{let after="";let total=0;for(let i=0;i<1000;i++){const r:any=await adminApi("/admin/taxonomy/sync",token,"POST",{limit:500,afterEditionId:after});total+=r.processed;if(!r.nextAfter)break;after=r.nextAfter;}toast.success(`Reclassified ${total} editions`);await reload();}catch(e){toast.error((e as Error).message)}};
  return <div><div className="staff-section-heading"><div><h2>Retail taxonomy</h2><p>Cove-owned hierarchy, independent of source metadata.</p></div><button className="button outline" onClick={sync}><RefreshCcw size={15}/>Reclassify catalog</button></div><div className="staff-three"><FormCard title={node.id?"Edit category":"New category"}><Field label="Name"><input value={node.name} onChange={e=>setNode({...node,name:val(e)})}/></Field><Field label="Slug"><input value={node.slug} onChange={e=>setNode({...node,slug:val(e).toLowerCase().replace(/[^a-z0-9-]/g,"-")})}/></Field><Field label="Parent"><select value={node.parentId} onChange={e=>setNode({...node,parentId:val(e)})}><option value="">Root</option>{data.nodes.filter((r:any)=>r.id!==node.id).map((r:any)=><option key={r.id} value={r.id}>{r.path}</option>)}</select></Field><Field label="Description"><textarea value={node.description} onChange={e=>setNode({...node,description:val(e)})}/></Field><Two><Field label="SEO title"><input value={node.seoTitle} onChange={e=>setNode({...node,seoTitle:val(e)})}/></Field><Field label="SEO description"><input value={node.seoDescription} onChange={e=>setNode({...node,seoDescription:val(e)})}/></Field></Two><Two><label className="staff-check"><input type="checkbox" checked={node.visible} onChange={e=>setNode({...node,visible:e.target.checked})}/>Visible</label><label className="staff-check"><input type="checkbox" checked={node.featured} onChange={e=>setNode({...node,featured:e.target.checked})}/>Featured</label></Two><SaveButton onClick={saveNode}/></FormCard><FormCard title="Source mapping rule"><Field label="Cove category"><select value={mapping.taxonomyNodeId} onChange={e=>setMapping({...mapping,taxonomyNodeId:val(e)})}><option value="">Choose…</option>{data.nodes.map((r:any)=><option key={r.id} value={r.id}>{r.path}</option>)}</select></Field><Two><Field label="Source scheme"><input value={mapping.sourceScheme} onChange={e=>setMapping({...mapping,sourceScheme:val(e)})}/></Field><Field label="Match mode"><select value={mapping.matchMode} onChange={e=>setMapping({...mapping,matchMode:val(e)})}><option>contains</option><option>prefix</option><option>exact</option></select></Field></Two><Field label="Source value"><input value={mapping.sourceValue} onChange={e=>setMapping({...mapping,sourceValue:val(e)})}/></Field><Two><Field label="Priority"><input type="number" value={mapping.priority} onChange={e=>setMapping({...mapping,priority:val(e)})}/></Field><label className="staff-check"><input type="checkbox" checked={mapping.active} onChange={e=>setMapping({...mapping,active:e.target.checked})}/>Active</label></Two><SaveButton onClick={saveMap}/></FormCard><Rows rows={data.nodes} title={(r)=>r.name} subtitle={(r)=>`${r.path} · ${r.visible?"visible":"hidden"}${r.featured?" · featured":""}`} onEdit={edit}/></div><div className="staff-split"><FormCard title="Manual edition classification"><Field label="Edition ID"><input value={manual.editionId} onChange={e=>setManual({...manual,editionId:val(e)})} placeholder="edition_…"/></Field><Field label="Cove categories"><select multiple value={manual.taxonomyNodeIds} onChange={(e)=>setManual({...manual,taxonomyNodeIds:Array.from(e.currentTarget.selectedOptions as HTMLCollectionOf<HTMLOptionElement>).map((o)=>o.value)})}>{data.nodes.map((r:any)=><option key={r.id} value={r.id}>{r.path}</option>)}</select></Field><p className="staff-help">Manual classifications survive supplier refreshes and are combined with mapped parent categories.</p><SaveButton onClick={saveManual}/></FormCard><div className="staff-list">{(data.manualAssignments||[]).map((r:any)=><button className="staff-list-row" key={r.edition_id} onClick={()=>setManual({editionId:r.edition_id,taxonomyNodeIds:String(r.taxonomy_node_ids||"").split(",").filter(Boolean)})}><strong>{r.edition_id}</strong><small>{r.taxonomy_paths}</small></button>)}</div></div></div>;
}

function Pages({token,rows,reload}:{token:string;rows:any[];reload:()=>Promise<void>}) {
  const [x,setX]=useState<any>({path:"/campaign/",pageType:"campaign",title:"",heading:"",description:"",eyebrow:"",seoTitle:"",seoDescription:"",query:"{}",status:"draft",territoryCode:"",languageCode:"",startsAt:"",endsAt:"",noindex:false});
  const edit=(r:any)=>setX({id:r.id,path:r.path,pageType:r.page_type,title:r.title,heading:r.heading,description:r.description,eyebrow:r.eyebrow,seoTitle:r.seo_title,seoDescription:r.seo_description,query:r.query_json||"{}",status:r.status,territoryCode:r.territory_code||"",languageCode:r.language_code||"",startsAt:r.starts_at||"",endsAt:r.ends_at||"",noindex:!!r.noindex});
  const save=async()=>{try{await adminApi("/admin/storefront/page",token,"POST",{...x,query:jsonObject(x.query),territoryCode:x.territoryCode||null,languageCode:x.languageCode||null,startsAt:x.startsAt||null,endsAt:x.endsAt||null});toast.success("Landing page saved");await reload();}catch(e){toast.error((e as Error).message)}};
  return <AdminSplit title="Landing pages" help="Publish durable campaign/browse URLs with their own SEO copy and preconfigured search filters. Core category URLs under /ebooks are generated from the taxonomy."><FormCard title={x.id?"Edit page":"New landing page"}><Two><Field label="Path"><input value={x.path} onChange={e=>setX({...x,path:val(e)})}/></Field><Field label="Status"><select value={x.status} onChange={e=>setX({...x,status:val(e)})}><option>draft</option><option>published</option><option>archived</option></select></Field></Two><Two><Field label="Title"><input value={x.title} onChange={e=>setX({...x,title:val(e)})}/></Field><Field label="Eyebrow"><input value={x.eyebrow} onChange={e=>setX({...x,eyebrow:val(e)})}/></Field></Two><Field label="Heading"><input value={x.heading} onChange={e=>setX({...x,heading:val(e)})}/></Field><Field label="Description"><textarea value={x.description} onChange={e=>setX({...x,description:val(e)})}/></Field><Field label="Search preset (JSON)"><textarea value={x.query} onChange={e=>setX({...x,query:val(e)})} placeholder='{"taxonomy":["fiction/fantasy"],"sort":"popular"}'/></Field><Two><Field label="Territory"><input value={x.territoryCode} maxLength={2} onChange={e=>setX({...x,territoryCode:val(e).toUpperCase()})} placeholder="Any"/></Field><Field label="Language"><input value={x.languageCode} onChange={e=>setX({...x,languageCode:val(e).toLowerCase()})} placeholder="Any"/></Field></Two><Two><Field label="Starts at"><input type="datetime-local" value={(x.startsAt||"").replace(/Z$/," ").trim().slice(0,16)} onChange={e=>setX({...x,startsAt:e.target.value?new Date(e.target.value).toISOString():""})}/></Field><Field label="Ends at"><input type="datetime-local" value={(x.endsAt||"").replace(/Z$/," ").trim().slice(0,16)} onChange={e=>setX({...x,endsAt:e.target.value?new Date(e.target.value).toISOString():""})}/></Field></Two><Two><Field label="SEO title"><input value={x.seoTitle} onChange={e=>setX({...x,seoTitle:val(e)})}/></Field><Field label="SEO description"><input value={x.seoDescription} onChange={e=>setX({...x,seoDescription:val(e)})}/></Field></Two><label className="staff-check"><input type="checkbox" checked={x.noindex} onChange={e=>setX({...x,noindex:e.target.checked})}/>Noindex this page</label><SaveButton onClick={save}/></FormCard><Rows rows={rows} title={(r)=>r.title} subtitle={(r)=>`${r.path} · ${r.status}`} onEdit={edit}/></AdminSplit>;
}

function Analytics({data}:{data:Snapshot}) {
  const totals=useMemo(()=>data.merch.analytics.reduce((a:any,r:any)=>({impressions:a.impressions+Number(r.impressions||0),clicks:a.clicks+Number(r.clicks||0)}),{impressions:0,clicks:0}),[data]);
  return <div><div className="staff-section-heading"><div><h2>Merchandising performance</h2><p>Thirty-day server-side placement impressions and clicks.</p></div></div><div className="staff-kpis"><Kpi label="Impressions" value={totals.impressions.toLocaleString()}/><Kpi label="Clicks" value={totals.clicks.toLocaleString()}/><Kpi label="CTR" value={totals.impressions?`${(100*totals.clicks/totals.impressions).toFixed(2)}%`:"—"}/><Kpi label="Active campaigns" value={String(data.merch.campaigns.filter((x:any)=>x.status==="published").length)}/></div><div className="staff-table">{data.merch.analytics.map((r:any)=><div className="staff-row" key={r.placement_id}><div><strong>{r.slot_key}</strong><small>{r.campaign_name}</small></div><span>{Number(r.impressions||0).toLocaleString()} impressions</span><span>{Number(r.clicks||0).toLocaleString()} clicks</span><span>{(Number(r.ctr||0)*100).toFixed(2)}% CTR</span><span>{Math.round(Number(r.avg_latency_ms||0))} ms · {Math.round(Number(r.avg_candidates||0))} candidates</span></div>)}</div>{data.merch.experimentAnalytics?.length>0&&<><h3 className="staff-audit-title">Experiment variants · last 30 days</h3><div className="staff-table">{data.merch.experimentAnalytics.map((r:any)=><div className="staff-row" key={`${r.experiment_id}:${r.variant||"unassigned"}`}><div><strong>{r.experiment_name}</strong><small>{r.variant||"unassigned"}</small></div><span>{Number(r.unique_viewers||0).toLocaleString()} viewers</span><span>{Number(r.impressions||0).toLocaleString()} impressions</span><span>{Number(r.clicks||0).toLocaleString()} clicks · {(Number(r.ctr||0)*100).toFixed(2)}% CTR</span></div>)}</div></>}<h3 className="staff-audit-title">Recent CMS audit</h3><div className="staff-table">{[...data.merch.audit,...data.taxonomy.audit].sort((a,b)=>String(b.created_at).localeCompare(String(a.created_at))).slice(0,50).map((r:any)=><div className="staff-row" key={r.id}><div><strong>{r.action} · {r.entity_type}</strong><small>{r.entity_id}</small></div><span>{new Date(r.created_at).toLocaleString()}</span></div>)}</div></div>;
}

function SecurityOperations({token}:{token:string}){
  const [data,setData]=useState<any|null>(null),[busy,setBusy]=useState("");
  const [incident,setIncident]=useState({severity:"sev3",title:"",customerImpact:""});
  const [edge,setEdge]=useState({environment:"production",provider:"cloudflare",wafMode:"block",managedRulesEnabled:true,botManagementMode:"challenge",ddosManaged:true,rateLimitPolicyRef:"",configReference:"",evidenceReference:""});
  async function load(){setBusy("load");try{setData(await adminApi<any>("/admin/security/status",token));}catch(e){toast.error((e as Error).message)}finally{setBusy("")}}
  useEffect(()=>{void load()},[token]);
  async function declare(){setBusy("incident");try{await adminApi("/admin/security/incident",token,"POST",incident);toast.success("Security incident declared");setIncident({...incident,title:"",customerImpact:""});await load();}catch(e){toast.error((e as Error).message)}finally{setBusy("")}}
  async function verifyEdge(){setBusy("edge");try{await adminApi("/admin/security/edge-control",token,"POST",edge);toast.success("Edge security evidence saved");await load();}catch(e){toast.error((e as Error).message)}finally{setBusy("")}}
  if(!data)return <div className="staff-auth"><ShieldCheck size={34}/><h2>Security program</h2><p>Security operations require the <code>security.read</code> permission and an AAL2 staff session.</p><button className="button outline" onClick={load}>Retry</button></div>;
  const openThreats=(data.threats||[]).filter((x:any)=>x.status==="open"),openFindings=(data.findings||[]).filter((x:any)=>["open","triaged","accepted"].includes(x.status)),openIncidents=(data.incidents||[]).filter((x:any)=>!["resolved","postmortem"].includes(x.status)),dueSecrets=(data.secrets||[]).filter((x:any)=>x.status==="rotation_due"||(x.next_rotation_at&&x.next_rotation_at<new Date().toISOString()));
  return <div className="staff-section"><div className="staff-section-head"><div><span className="small-label">THREATS · SUPPLY CHAIN · EDGE · INCIDENTS</span><h2>Security program</h2><p>Evidence-backed controls. Production WAF/DDoS, scans, secrets, build provenance, pentests, malware quarantine, and incident response are tracked here instead of as deployment folklore.</p></div><button className="button outline" onClick={load} disabled={!!busy}><RefreshCcw size={15}/>Refresh</button></div>
    <div className="staff-stats"><Metric label="Open threats" value={openThreats.length}/><Metric label="Open findings" value={openFindings.length}/><Metric label="Open incidents" value={openIncidents.length}/><Metric label="Rotation due" value={dueSecrets.length}/></div>
    <div className="staff-grid two-col"><FormCard title="Verify edge protection"><Two><Field label="Environment"><select value={edge.environment} onChange={e=>setEdge({...edge,environment:val(e)})}><option>production</option><option>staging</option></select></Field><Field label="Provider"><input value={edge.provider} onChange={e=>setEdge({...edge,provider:val(e)})}/></Field></Two><Two><Field label="WAF"><select value={edge.wafMode} onChange={e=>setEdge({...edge,wafMode:val(e)})}><option>block</option><option>monitor</option><option>off</option></select></Field><Field label="Bot policy"><select value={edge.botManagementMode} onChange={e=>setEdge({...edge,botManagementMode:val(e)})}><option>challenge</option><option>block</option><option>monitor</option><option>off</option></select></Field></Two><Field label="Config reference"><input value={edge.configReference} onChange={e=>setEdge({...edge,configReference:val(e)})} placeholder="provider policy/dashboard reference"/></Field><Field label="Verification evidence"><input value={edge.evidenceReference} onChange={e=>setEdge({...edge,evidenceReference:val(e)})} placeholder="immutable report/artifact reference"/></Field><button className="button gold" onClick={verifyEdge} disabled={!!busy}>Save verified control</button></FormCard>
    <FormCard title="Declare incident"><Two><Field label="Severity"><select value={incident.severity} onChange={e=>setIncident({...incident,severity:val(e)})}><option>sev1</option><option>sev2</option><option>sev3</option><option>sev4</option></select></Field><Field label="Title"><input value={incident.title} onChange={e=>setIncident({...incident,title:val(e)})}/></Field></Two><Field label="Known customer impact"><textarea value={incident.customerImpact} onChange={e=>setIncident({...incident,customerImpact:val(e)})}/></Field><button className="button gold" onClick={declare} disabled={!!busy||!incident.title}>Declare incident</button></FormCard></div>
    <h3 className="staff-audit-title">Highest-risk open threats</h3><div className="staff-table">{openThreats.slice(0,20).map((r:any)=><div className="staff-row" key={r.id}><div><strong>{r.title}</strong><small>{r.category} · {r.owner_team}</small></div><span>risk {r.risk_score}/25</span><span>{r.treatment}</span></div>)}</div>
    <h3 className="staff-audit-title">Open security findings</h3><div className="staff-table">{openFindings.slice(0,30).map((r:any)=><div className="staff-row" key={r.id}><div><strong>{r.title}</strong><small>{r.component||r.category}</small></div><span>{r.severity}</span><span>{r.due_at?new Date(r.due_at).toLocaleDateString():"triage"}</span></div>)}</div>
    <h3 className="staff-audit-title">Recent malware / supply-chain scans</h3><div className="staff-table">{(data.scans||[]).slice(0,30).map((r:any)=><div className="staff-row" key={r.id}><div><strong>{r.scan_type} · {r.target_type}</strong><small>{r.scanner} {r.scanner_version||""}</small></div><span>{r.status}</span><span>{new Date(r.created_at).toLocaleString()}</span></div>)}</div>
  </div>;
}

function AdminSplit({title,help,children}:{title:string;help:string;children:ReactNode}) { return <div><div className="staff-section-heading"><div><h2>{title}</h2><p>{help}</p></div></div><div className="staff-split">{children}</div></div>; }
function FormCard({title,children}:{title:string;children:ReactNode}) { return <section className="staff-form"><h3>{title}</h3>{children}</section>; }
function Field({label,children}:{label:string;children:ReactNode}) { return <label className="staff-field"><span>{label}</span>{children}</label>; }
function Two({children}:{children:ReactNode}) { return <div className="staff-two">{children}</div>; }
function SaveButton({onClick}:{onClick:()=>void}) { return <button className="button gold" onClick={onClick}><Save size={15}/>Save</button>; }
function Rows({rows,title,subtitle,onEdit}:{rows:any[];title:(r:any)=>string;subtitle:(r:any)=>string;onEdit:(r:any)=>void}) { return <div className="staff-list">{rows.map((r:any)=><button className="staff-list-row" key={r.id} onClick={()=>onEdit(r)}><strong>{title(r)}</strong><small>{subtitle(r)}</small></button>)}</div>; }
function Kpi({label,value}:{label:string;value:string}) { return <div className="staff-kpi"><small>{label}</small><strong>{value}</strong></div>; }
